 do {changed=false;
  outer:for(int i=0;i<a.size();i++) for(int j=i+1;j<a.size();j++) {
   int[] x=a.get(i),y=a.get(j);
   if(x[0]<=y[1] && y[0]<=x[1]){x[0]=Math.min(x[0],y[0]);x[1]=Math.max(x[1],y[1]);a.remove(j);changed=true;break outer;}
  }
 }while(changed);
 return a.toArray(new int[0][]);
}

