public int findKthLargest(int[] nums,int k) {
 boolean[] used=new boolean[nums.length];int best=-1;
 for(int rank=0;rank<k;rank++) {
  best=-1;for(int i=0;i<nums.length;i++) if(!used[i] && (best<0 || nums[i]>nums[best])) best=i;
  used[best]=true;
 }return nums[best];
}

